window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['adsp-38']={"round":38,"cert":"adsp","questions":[{"id":"62252","number":1,"category":"데이터 이해","type":"choice","subject":"데이터베이스의 구성 요소에 대한 설명이다. 각각 무엇에 대한 설명인가?","extra":"<pre class=\"contents\">가. 데이터를 설명해주는 데이터로 데이터의 특성, 구조, 정의 및 관리 정보를 설명하는 데이터\r\n나. 데이터를 빠르고 쉽게 찾을 수 있게 해주는 자료 구조</pre>","choices":[{"n":1,"html":"가) 테이블,  나) 인덱스"},{"n":2,"html":"가) 메타 데이터,  나) 인덱스"},{"n":3,"html":"가) 메타 데이터,  나) 속성"},{"n":4,"html":"가) 테이블,  나) 속성"}],"answer":[2],"explain":{"ai":["<p>가에 대한 설명은 데이터베이스 내에서 데이터의 특성, 구조, 정의, 그리고 관리에 필요한 정보를 제공하는 메타 데이터를 의미합니다. 이는 데이터 자체를 설명하고 이해하는 데 필수적인 요소입니다.</p>\n<p>나에 대한 설명은 데이터베이스 내의 데이터를 효율적으로 검색하고 접근할 수 있도록 설계된 구조를 가리키며, 이는 인덱스에 해당합니다. 인덱스는 데이터 검색 속도를 크게 향상시키는 역할을 합니다.</p>\n<p>따라서 올바른 짝짓기는:</p>\n<ul>\n<li>가) 메타 데이터</li>\n<li>나) 인덱스</li>\n</ul>\n<p>정답은 2번입니다.</p>"]},"rate":87,"rateN":5614},{"id":"62253","number":2,"category":"데이터 이해","type":"choice","subject":"다음 중 상용 DB가 아닌 것은 무엇인가?","choices":[{"n":1,"html":"DB2"},{"n":2,"html":"Tableau"},{"n":3,"html":"SQL Server"},{"n":4,"html":"Oracle"}],"answer":[2],"explain":{"ai":["<p>정답은 2번 Tableau입니다. DB2, SQL Server, Oracle은 모두 전통적인 관계형 데이터베이스 관리 시스템(RDBMS)으로, 데이터의 저장, 관리, 쿼리 처리 등을 전문적으로 수행하는 상용 데이터베이스 시스템입니다. 반면에 Tableau는 주로 데이터 시각화와 분석에 초점을 맞춘 비즈니스 인텔리전스(BI) 도구입니다. Tableau는 데이터를 수집하고 이를 직관적인 차트나 대시보드로 시각화하는데 특화되어 있어, 순수한 데이터베이스 관리 기능보다는 분석 및 보고에 중점을 두고 있습니다. 따라서 이 문제에서 상용 DB가 아닌 옵션으로 분류됩니다.</p>"]},"rate":63,"rateN":6524},{"id":"62254","number":3,"category":"데이터 이해","type":"choice","subject":"데이터 크기를 작은 것 부터 큰 것 순서로 올바르게 나열한 것은?","choices":[{"n":1,"html":"PB < EB < ZB < YB"},{"n":2,"html":"PB < YB < EB < ZB"},{"n":3,"html":"YB < ZB < EB < PB"},{"n":4,"html":"PB < ZB < EB < YB"}],"answer":[1],"explain":{"ai":["<p>데이터 크기의 단위는 바이트를 기준으로 한다. 데이터 크기 단위를 작은 것부터 큰 순서대로 나열하면 다음과 같다. \n바이트, 킬로바이트, 메가바이트, 기가바이트, 테라바이트, 페타바이트, 엑사바이트, 제타바이트, 요타바이트 순이다. \n따라서 페타바이트 보다 엑사바이트이 더 크고 엑사바이트 보다는 제타바이트가 더 크며 제타바이트 보다는 요타바이트가 더 크다. \n즉 페타바이트 &lt; 엑사바이트 &lt; 제타바이트 &lt; 요타바이트이므로 데이터 크기를 작은 것부터 큰 순으로 나열한 것은 1번이다.</p>"]},"rate":83,"rateN":5588},{"id":"62255","number":4,"category":"데이터 이해","type":"choice","subject":"다음 데이터베이스의 특징에 대한 설명 중 옳지 않은 것은 무엇인가?","choices":[{"n":1,"html":"통합된 데이터로 동일한 내용의 데이터가 중복되어 저장된다."},{"n":2,"html":"저장된 데이터로 컴퓨터가 접근할 수 있는 저장 매체에 저장된다."},{"n":3,"html":"공용 데이터로 여러 사용자에게 서로 다른 목적으로 데이터가 공동 이용된다."},{"n":4,"html":"변화되는 데이터로 항상 변화하면서도 항상 현재의 정확한 데이터를 유지해야한다."}],"answer":[1],"explain":{"ai":["<p>데이터베이스의 특징 중 옳지 않은 것은 1번이다. 데이터베이스는 통합된 데이터로 동일한 내용의 데이터가 중복되어 저장되지 않는다. 데이터베이스는 데이터를 효율적으로 관리하기 위해 중복을 최소화하고 일관성을 유지해야 한다. 따라서 동일한 내용의 데이터가 중복되어 저장되는 것은 데이터베이스의 특징이 아니다.</p>\n<p>데이터베이스의 특징은 다음과 같다. 저장된 데이터는 컴퓨터가 접근할 수 있는 저장 매체에 저장되어야 하며, 공용 데이터로 여러 사용자에게 서로 다른 목적으로 데이터가 공동 이용될 수 있다. 또한 데이터베이스는 변화되는 데이터를 항상 변화하면서도 항상 현재의 정확한 데이터를 유지해야 한다. 이러한 특징들이 데이터베이스를 효율적으로 관리하고 활용하는 데 중요한 역할을 한다.</p>"]},"rate":94,"rateN":4997},{"id":"62256","number":5,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터 활용을 위한 3요소에 대한 내용으로 틀린 것은?","choices":[{"n":1,"html":"데이터 : 모든 것의 데이터화"},{"n":2,"html":"기술 : 진화하는 알고리즘 , 인공지능"},{"n":3,"html":"인력 : 데이터 사이언티스트, 알고리즈미스트"},{"n":4,"html":"프로세스 : 이전과는 다른 데이터 관리를 위한 작업절차"}],"answer":[4],"explain":{"ai":["<p>빅데이터 활용을 위한 3요소는 데이터, 기술, 인력입니다. 데이터는 모든 것이 데이터화되는 것을 의미하며, 기술은 진화하는 알고리즘과 인공지능을 말합니다. 인력은 데이터 사이언티스트와 알고리즈미스트를 가리킵니다. </p>\n<p>그러나 4번 프로세스는 빅데이터 활용을 위한 3요소 중 하나가 아닙니다. 프로세스는 데이터 관리의 과정이나 노력 等을 의미할 수 있으나, 빅데이터 활용의 3요소는 데이터, 기술, 인력으로 정의되기 때문에 4번이 틀린 내용입니다. 따라서 정답은 4번입니다.</p>"]},"rate":77,"rateN":5959},{"id":"62257","number":6,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터로 인한 본질적인 변화로 옳지 않은 것은?","extra":"<pre class=\"contents\">가. 이미 가치가 있을 것이라고 정해진 특정한 정보만 모아서 처리하던 것을 가능한 많은 데이터를 모으고 다양한 방식으로 조합해 숨은 정보를 찾아낸다.\r\n나. 일부 데이터의 샘플링을 통한 표본조사를 수행하는 환경으로 변화되었다.\r\n다. 질보다 양의 관점을 갖는다.\r\n라. 인과관계에 의한 미래 예측이 데이터 기반의 상관관계 분석을 점점 더 압도하는 추세이다.</pre>","choices":[{"n":1,"html":"가, 나"},{"n":2,"html":"나, 라"},{"n":3,"html":"가, 다"},{"n":4,"html":"다, 라"}],"answer":[2],"explain":{"ai":["<p>빅데이터로 인한 본질적인 변화 중 옳지 않은 것은 나와 라를 선택해야 한다. </p>\n<p>빅데이터는 가능한 많은 데이터를 모으고 다양한 방식으로 조합해 숨은 정보를 찾아내는 특징이 있다. 이를 통해 데이터의 양이 중요해지고 데이터 기반의 상관관계 분석이 중요해졌다. 이러한 특징은 빅데이터가 데이터 처리와 분석의 새로운 패러다임을 가져왔음을 의미한다.</p>\n<p>빅데이터는 일부 데이터의 샘플링을 통한 표본조사를 수행하는 환경이 아니다. 데이터의 양이 많아질수록 전체 데이터를 분석하는 것이 가능해져서 표본조사의 필요성이 줄어든다. 또한 빅데이터는 인과관계에 의한 미래 예측보다 데이터 기반의 상관관계 분석을 더 중시한다. 빅데이터를 통한 분석은 데이터의 패턴과 상관관계를 기반으로 미래를 예측하는 데 중점을 둔다. </p>\n<p>따라서 빅데이터로 인한 본질적인 변화 중 옳지 않은 것은 나와 라이다.</p>"]},"rate":68,"rateN":6266},{"id":"62258","number":7,"category":"데이터 이해","type":"choice","subject":"빅데이터의 위기 요인이 아닌 것은?","choices":[{"n":1,"html":"익명화"},{"n":2,"html":"사생활 침해"},{"n":3,"html":"데이터 오용"},{"n":4,"html":"책임원칙의 훼손"}],"answer":[1],"explain":{"ai":["<p>빅데이터의 위기 요인은 다양한 개인 정보나 데이터의 유출, 과도한 데이터 수집, 데이터의 부정확성 등이 있습니다. 익명화는 데이터의 개인 정보를 보호하기 위해 진행하는 과정으로, 데이터의 개인 정보를 삭제하거나 수정하여 데이터 주체를 식별할 수 없게 하는 것입니다. </p>\n<p>비교적 다른 선택지들은 데이터의 불법적 이용이나 데이터의 오남용에 관련이 있습니다. 사생활 침해는 개인의 사생활을 침해하는 것을 말합니다. 데이터 오용은 데이터를 잘못 사용하거나 악의적으로 사용하는 것을 말합니다. 책임원칙의 훼손은 데이터를 관리하고 있는 주체가 데이터의 관리에 대한 책임을 지지 않는 것을 말합니다.</p>\n<p>따라서 익명화는 데이터의 보호를 위해進行하는 과정으로 데이터의 위기 요인이 아닙니다. regexp_callbacks정리 하면 정답은 1번입니다.</p>"]},"rate":92,"rateN":5287},{"id":"62259","number":8,"category":"데이터 이해","type":"choice","subject":"데이터 사이언티스트가 가져야 할 역량 중 종류가 다른 하나는?","choices":[{"n":1,"html":"다분야간 협력"},{"n":2,"html":"통찰력 있는 분석"},{"n":3,"html":"설득력 있는 전달"},{"n":4,"html":"빅데이터에 대한 이론적 지식"}],"answer":[4],"explain":{"ai":["<p>데이터 사이언티스트가 가져야 할 역량은 다양한 분야에서 발생하는 데이터를 효율적으로 분석하고 기업의 의사 결정에 기여할 수 있는 능력입니다. 종류가 다른 하나는 빅데이터에 대한 이론적 지식입니다. 데이터 사이언티스트는 데이터를 분석하고 해석하는 데 필요한 다양한 기법과 도구를 이해해야 하며, 이를 위해 빅데이터에 대한 이론적 지식이 필요합니다. 이는 데이터를 수집하고 저장하고 처리하는 것에 대한 지식이 포함되어 있으며, 데이터 사이언티스트가 데이터를 효과적으로 분석하고 해석할 수 있도록 합니다. </p>\n<p>다분야간 협력, 통찰력 있는 분석, 설득력 있는 전달은 모두 데이터 사이언티스트가 가져야 할 중요한 역량입니다. 그러나 빅데이터에 대한 이론적 지식은 데이터를 분석하고 해석하는 데 필요한 기반 지식을 제공하기 때문에 데이터 사이언티스트에게 필수적인 역량입니다.</p>"]},"rate":76,"rateN":6014},{"id":"62260","number":9,"category":"데이터 이해","type":"short","subject":"기업이 외부 공급업체 또는 제휴업체와 통합된 정보시스템으로 연계하여 시간과 비용을 최적화 시키기 위한 솔루션은 무엇인가?","shortAnswer":"SCM","explain":{"ai":["<p>해당 문제의 정답은 수급鏈 관리 솔루션을 뜻하는 SCM이다. 기업은 외부 공급업체나 제휴업체와의 협력을 강화하기 위해 통합된 정보시스템을 활용하고 있다. 탁월한 SCM은 제조, 물류, 재고 관리 等 비즈니스 프로세스를 최적화하여 기업의 전체 비용을 절감하고 효율성을 높인다. 또한 SCM을 통하여 기업은 시간과 비용을 최적화 하는데 도움을 받을 수 있다.ollo継속해서 기업의 경쟁력을 강화하고 고객 만족도를 향상시킬 수 있다.</p>"]}},{"id":"62261","number":10,"category":"데이터 이해","type":"short","subject":"데이터, 정보, 지식을 통해 최종적으로 지혜를 얻어내는 과정을 계층구조로 설명하는 것은 무엇인가?","shortAnswer":"DIKW","wiki":[{"title":"DIKW 피라미드","url":"https://itwiki.kr/w/DIKW 피라미드"}],"explain":{"ai":["<p>DIKW 계층구조는 데이터, 정보, 지식, 지혜의Clause를 설명하는 모델이다. 이 모델에 따르면 데이터는.raw事実이나 数値などの 기본적인 사실이다. 정보는 데이터를 구성하고 처리하여 의미를 부여한 결과물이다. 지식은 정보를 분석하고 해석하여 얻은 결과물이다. 지혜는 지식에 경험이나洞察력을 더하여 얻은 깊은 이해이다. 따라서 DIKW 계층구조는 데이터에서 정보, 지식, 지혜로 거듭하여 발전하는 과정을 나타낸다.</p>"]}},{"id":"62262","number":11,"category":"데이터분석 기획","type":"choice","subject":"데이터 분석 수준 진단 결과에서 분석 준비도와 분석 성숙도 둘 다 낮은 경우에 해당하는 것은?","choices":[{"n":1,"html":"정착형"},{"n":2,"html":"확산형"},{"n":3,"html":"준비형"},{"n":4,"html":"도입형"}],"answer":[3],"explain":{"ai":["<p>데이터 분석 수준 진단 결과에서 분석 준비도와 분석 성숙도 둘 다 낮은 경우를 준비형이라고 합니다. 준비형은 데이터 분석을 처음 도입하거나 준비단계에 있기 때문에 분석 준비도와 성숙도가 저조한 것을 의미합니다. 따라서 분석을 활성화하고 확산시키기 위해 추가적인 투자와 노력이 필요합니다.</p>"]},"rate":77,"rateN":5543},{"id":"62264","number":12,"category":"데이터분석 기획","type":"choice","subject":"다음 중 비즈니스 모델 캔버스를 활용한 과제 발굴 영역으로 틀린 것은?","choices":[{"n":1,"html":"혁신"},{"n":2,"html":"업무"},{"n":3,"html":"고객"},{"n":4,"html":"제품"}],"answer":[1],"explain":{"ai":["<p>비즈니스 모델 캔버스를 활용한 과제 발굴 영역은 주로 업무, 고객, 제품 등과 관련이 있습니다. 비즈니스 모델 캔버스는 기업의 비즈니스 모델을 віз覺적으로 표현하는 도구로, 고객 세분화, 가치 제안, 채널, 고객 관계, 수입 원천 등 다양한 요소를 포함합니다. </p>\n<p>업무와 관련된 영역은 회사 내부의 프로세스와 관련이 있으며, 고객 영역은 고객의需求과 관련이 있습니다. 제품 영역은 회사에서 제공하는 제품과 서비스와 관련이 있습니다. </p>\n<p>그러나 혁신은 비즈니스 모델 캔버스를 활용한 과제 발굴 영역으로 적합하지 않습니다. 혁신은 더 일반적인概念으로, 새로운 기술이나 아이디어를 도입하여 사업을 발전시키는 것을 의미합니다. 비즈니스 모델 캔버스를 활용한 과제 발굴은 더 cụ thể한 비즈니스 모델의 각 요소에 초점을 맞추는 반면, 혁신은 더广い 의미를 가지고 있습니다. 따라서 1번 혁신이 잘못된 선택입니다.</p>"]},"rate":68,"rateN":5913},{"id":"62263","number":13,"category":"데이터분석 기획","type":"choice","subject":"다음 분석과제의 우선순위 선정 관련 설명 중 틀린 것은?","choices":[{"n":1,"html":"우선순위를 시급성에 둔다면 III - IV - II 순서로 진행한다."},{"n":2,"html":"우선순위를 난이도에 둔다면 III - I - II 순서로 진행한다."},{"n":3,"html":"시급성과 난이도 둘 다 높은 것이 우선순위가 가장 높다."},{"n":4,"html":"시급성의 판단 기준은 전략적 중요도가 핵심이다."}],"answer":[3],"explain":{"ai":["<p>우선순위를 결정할 때는 시급성과 난이도를 모두 고려해야 한다. 하지만 두 가지를 모두 높은 순으로 우선순위를 결정하는 것은 올바르지 않다. 시급성과 난이도는 서로 다른 관점에서 고려해야 하는 요소이다. 시급성은 분석과제를 수행해야 하는 긴급성이나 중요성을 의미하고, 난이도는 분석과제를 수행하는 데 필요한 복잡성이나 어려움을 의미한다. 따라서 시급성과 난이도를 모두 고려하여 우선순위를 결정해야 하며, 둘 다 높은 것이 항상 우선순위가 가장 높은 것은 아니다. 다른 요인들 тоже 고려해야 한다. 이러한 이유로 3번이 틀린 설명이다.</p>"]},"rate":78,"rateN":5393},{"id":"62265","number":14,"category":"데이터분석 기획","type":"choice","subject":"다음 분석 성숙도 관련 내용으로 옳지 않은 것은?","choices":[{"n":1,"html":"유사 업종, 경쟁 업체와의 비교 분석을 포함한다."},{"n":2,"html":"성숙도 수준에 따라 도입, 활용, 확산, 최적화 단계로 구분해 살펴 볼 수 있다."},{"n":3,"html":"시스템 개발 업무능력과 조직의 성숙도 파악을 위해 CMMI 모델을 활용하여 분석 성숙도를 평가한다."},{"n":4,"html":"데이터 분석 수준 진단은 분석 준비도와 분석 성숙도를 함께 평가함으로써 수행될 수 있다."}],"answer":[1],"explain":{"ai":["<p><b>정답: 1번</b></p>\n<p>분석 성숙도는 주로 조직 내 데이터와 분석의 활용 및 관리 수준을 평가하는 개념으로, 주로 내부 프로세스와 역량에 초점을 맞춥니다. 따라서, <b>1번 보기의 \"유사 업종, 경쟁 업체와의 비교 분석을 포함한다\"</b>는 분석 성숙도의 정의와 직접적으로 맞지 않습니다. 분석 성숙도 평가는 주로 내부의 진행 상황과 개선 영역에 중점을 두기 때문에 외부 업체와의 비교는 해당 개념의 핵심 범위를 벗어납니다. </p>\n<p>나머지 보기들은 분석 성숙도 평가와 관련된 정확한 내용을 담고 있습니다:</p>\n<ul>\n<li><b>2번</b>은 일반적인 성숙도 모델의 단계를 잘 설명합니다.</li>\n<li><b>3번</b>은 조직의 전반적인 프로세스 성숙도 평가 모델인 CMMI를 언급하며, 분석 성숙도와 유사한 맥락에서 활용될 수 있음을 시사합니다.</li>\n<li><b>4번</b>은 분석 성숙도 평가가 준비도와 함께 이루어진다는 정확한 설명입니다.</li>\n</ul>"]},"rate":55,"rateN":6720},{"id":"62266","number":15,"category":"데이터분석 기획","type":"choice","subject":"분석 마스터플랜 수립 시 적용 범위/ 방식의 고려 요소가 아닌 것은?","choices":[{"n":1,"html":"업무 내재화 적용 수준"},{"n":2,"html":"분석 데이터 적용 수준"},{"n":3,"html":"기술 적용 수준"},{"n":4,"html":"실행 용이성"}],"answer":[4],"explain":{"ai":["<p>분석 마스터플랜 수립 시 고려해야 하는 요소에는 여러 가지가 있습니다. 먼저 업무 내재화 적용 수준은분석을 실제 업무에 어떻게 내재화할지에 대한 고려입니다. 분석 데이터 적용 수준은 분석에 필요한 데이터를 어떻게 수집하고 관리할지에 대한 고려입니다. 기술 적용 수준은 어떤 기술을 사용하여 분석을 수행할지에 대한 고려입니다. </p>\n<p>하지만 실행 용이성은 분석 마스터플랜 수립 시 고려하는 요소가 아닙니다. 실행 용이성은 분석이 수행되기 위한 과정에서 고려하는 요소입니다. 따라서 분석 마스터플랜 수립 시 적용 범위와 방식의 고려 요소가 아닌 것은 실행 용이성입니다.</p>"]},"rate":47,"rateN":7640},{"id":"62267","number":16,"category":"데이터분석 기획","type":"choice","subject":"데이터 분석을 위한 분석 업무 조직 구조에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"집중형 조직 구조는 일부 협업 부서와 분석 업무가 중복 또는 이원화 될 가능성이 있다."},{"n":2,"html":"기능 중심 조직 구조는 전사적 관점에서 핵심 분석이 어렵다."},{"n":3,"html":"분산 조직 구조는 분석 결과 실무 적용에 대한 대응이 느리다."},{"n":4,"html":"분석 조직의 인력들이 협업 부서에 배치되어 업무를 수행하는 것은 분산 조직 구조이다."}],"answer":[3],"explain":{"ai":["<p>정답은 3번입니다. 분산 조직 구조는 각 부서 내에 분석 전문가가 배치되어 있어, 실제 업무와 밀접하게 연관된 분석을 빠르게 수행하고 그 결과를 실시간으로 적용할 수 있는 장점이 있습니다. 따라서 \"분석 결과 실무 적용에 대한 대응이 느리다\"는 설명이 맞지 않습니다. 실제로 분산 구조는 빠른 의사결정과 현장 맞춤형 분석을 가능하게 합니다. 반면, 집중형 조직은 중앙 집중화된 분석 팀이 있어 중복이 발생할 수 있고, 기능 중심 구조는 부서 간 장벽으로 인해 전사적 시각에서의 통합 분석이 어려울 수 있습니다. 분석 인력이 협업 부서에 배치되는 것은 분산 조직 구조의 특징 중 하나이므로, 4번도 사실에 가깝지만 문제의 질문에서 옳지 않은 설명을 찾는 것이므로 정답은 3번이 됩니다.</p>"]},"rate":67,"rateN":5992},{"id":"62268","number":17,"category":"데이터분석 기획","type":"choice","subject":"분석 활용 시나리오에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"데이터 확보가 가장 중요하다."},{"n":2,"html":"데이터 분석을 특정 목적에 맞게 활용하는 방법 또는 계획을 의미한다."},{"n":3,"html":"분석 목표와 분석 방법을 설명하고 예상 결과를 제시하는 문서이다."},{"n":4,"html":"프로젝트 진행 중에도 변경될 수 있다."}],"answer":[1],"explain":{"ai":["<p>분석 활용 시나리오는 데이터 분석을 특정 목적에 맞게 활용하는 방법 또는 계획을 의미한다. 이를 위해 분석 목표와 분석 방법을 설명하고 예상 결과를 제시하는 문서로 정의할 수 있다. 또한 프로젝트 진행 중에도 변경될 수 있다. 하지만 데이터 확보가 가장 중요하다는 것은 분석 활용 시나리오를 설명하는 내용이 아니다. 데이터 확보는 중요한 과정이나 분석 활용 시나리오에 대한 설명과는 다르기 때문이다.</p>"]},"rate":56,"rateN":6674},{"id":"62269","number":18,"category":"데이터분석 기획","type":"choice","subject":"분석 기획 시 고려해야 할 것으로 적절하지 않은 것은?","choices":[{"n":1,"html":"데이터 확보가 될 수 있는지, 데이터 유형에 대한 분석이 필요하다."},{"n":2,"html":"비용보다 분석력에 최우선 해야 한다."},{"n":3,"html":"기준에 잘 구현되어 활용되고 있는 유사 시나리오 및 솔루션을 최대한 활용한다."},{"n":4,"html":"장애요소에 대한 사전 계획 수립이 고려 되어야 한다."}],"answer":[2],"explain":{"ai":["<p>분석 기획 시 중요한 고려 사항은 데이터 확보의可能性, 데이터 유형에 대한 분석, 기준으로 잘 구현되어 활용되고 있는 유사 시나리오 및 솔루션의 활용, 장애요소에 대한 사전 계획 수립이다. 하지만 비용보다 분석력에 최우선한다는 것은 적절하지 않은 고려 사항이다. 분석力的 우선은 중요하지만 비용에 대한 고려도 함께 이루어져야 하며, 모든 프로젝트는 제한된 자원과 비용 안에서 수행되기 때문이다. 따라서 분석 기획시 비용과 분석력 사이에서 적절한 균형을 찾는 것이 중요하다.</p>"]},"rate":80,"rateN":5282},{"id":"62270","number":19,"category":"데이터분석 기획","type":"short","subject":"데이터 분석 준비도 프레임워크에서 운영 시스템 데이터 통합, EAI ETL등 데이터 유통체계 분석 및 전용 서버 및 스토리지, 빅데이트 분석 환경, 비주얼 분석 환경 등과 관련된 항목은 무엇인가?","shortAnswer":"분석 인프라 (IT 인프라)","explain":{"ai":["<p>데이터 분석 준비도 프레임워크에서 운영 시스템 데이터 통합, EAI, ETL 등 데이터 유통체계 분석 및 전용 서버 및 스토리지, 빅데이터 분석 환경, 비주얼 분석 환경 등과 관련된 항목은 분석 인프라 즉 IT 인프라를 말한다. \n분석 인프라는 데이터 분석을 위한 기술적인 기반을 의미하며 데이터를 수집, 저장, 처리, 분석하기 위한 하드웨어와 소프트웨어 리소스를 포함한다. \n따라서 분석 인프라에는 서버, 스토리지, 네트워크, 데이터베이스, 분석 소프트웨어 등이 포함된다. \nопер레이팅 시스템 데이터 통합, EAI, ETL 等의 데이터 유통체계 분석 및 전용 서버 및 스토리지, 빅데이터 분석 환경, 비주얼 분석 환경 등이分析 인프라에 해당한다.</p>"]}},{"id":"62271","number":20,"category":"데이터분석 기획","type":"short","subject":"다음 빈칸에 알맞은 용어는 무엇인가?","extra":"<pre class=\"contents\">기존의 논리적인 단계별 접근법에 기반한 문제 해결 방식은 최근 복잡하고 다양한 환경에서 발생하는 문제에 적합하지 않을 수 있다. 이를 해결하기 위해 (        ) 접근법을 통해 전통적인 분석적 사고를 극복하려고 한다. \r\n이 접근법은 상향식 방식의 발산단계와 도출된 옵션을 분석하고 검증하는 하향식 접근방식의 수렴단계를 반복하여 과제를 발굴한다.</pre>","shortAnswer":"디자인 사고(Design Thinking)","explain":{"ai":["<p>해석: 디자인 사고(Design Thinking) 접근법은 기존의 논리적인 단계별 접근법을 기반으로 하는 문제 해결 방식의 한계를 극복하기 위해 사용된다. 최근의 복잡하고 다양한 문제에 효과적으로 대처하기 위한 전략이다. </p>\n<p>디자인 사고(Design Thinking)는 사용자 중심의 설계过程를 강조하며, 문제 정의, 아이디어 생성, Prototyping, 테스트의 반복적인 단계를 통해 해결책을 찾는다. 디자인 사고를 통해 전통적인 분석적 사고를 극복하고, 창의적이고 혁신적인 문제 해결 방식을 도모할 수 있다. </p>\n<p>상향식 방식의 발산단계에서는 다양한 관점과 아이디어를 수집하며, 하향식 접근방식의 수렴단계에서는 도출된 옵션을 분석하고 검증하여 최적의 해결책을 찾는 것이다. 이러한 반복적인 processo를 통해 효과적이고 혁신적인 문제 해결 방안을 개발할 수 있다.</p>"]}},{"id":"62272","number":21,"category":"데이터분석","type":"choice","subject":"수면 유도제 데이터를 통한 t-test 결과이다. 다음 중 결과 해석이 적절하지 않은 것은?","choices":[{"n":1,"html":"수면유도제 2가 수면유도제 1보다 효과적이다."},{"n":2,"html":"유의수준 0.05하에서 두 집단의 평균이 동일하다는 귀무가설을 채택할 수 있다."},{"n":3,"html":"두 개의 표본 집단이 크기가 클경우(N>30) 집단의 정규성 검증없이 이 표본 t검정을 사용할 수 있다."},{"n":4,"html":"독립표본 t검정 분석 전에 등분산 검정을 실시한다."}],"answer":[1],"explain":{"ai":["<p>t-test 결과는 두 집단의 평균 차이가 통계적으로 유의한지를 검정하는 것이지, 두 집단 중 어떤 것이 더 효과적인지를 비교하는 것이 아님. 따라서 수면유도제 2가 수면유도제 1보다 효과적이라고 해석하는 것은 적절하지 않음. </p>\n<p>결과 해석이 적절하지 않은 것은 1번, 즉 수면유도제 2가 수면유도제 1보다 효과적이라는 결론을 내리는 것임. </p>\n<p>그 외의 선택지 2, 3, 4번은 t-test 결과 해석에 적절함.</p>"]},"rate":37,"rateN":4199},{"id":"62273","number":22,"category":"데이터분석","type":"choice","subject":"다음 중 분류 모형 평가에 사용되는 도구가 아닌 것은?","choices":[{"n":1,"html":"ROC 그래프"},{"n":2,"html":"덴드로그램"},{"n":3,"html":"향상도 곡선"},{"n":4,"html":"이익 도표"}],"answer":[2],"explain":{"ai":["<p>분류 모형의 성능을 평가하는 방법에는 여러 가지 장치와 도구가 있습니다. ROC 그래프는 실제 양성과 음성을 예측한 값을 바탕으로 sensitivity와 specificity에 대한 학교 그래프를 그려서 평가합니다. 향상도 곡선은 모델의 성능과 실제 발생한 장애를 비교해 볼 때 사용하며 이익 도표는 분류 모델의 성능에 대해 비용과 상관관계를 분석할 때 사용합니다. </p>\n<p>하지만 덴드로그램은 계층적 군집 분석의 결과를 시각화하여 나타내는 도구로, 분류 모형의 성능을 평가하는 데 사용되는 것이 아닙니다. 그러므로 분류 모형 평가에 사용되는 도구가 아닌 것은 덴드로그램입니다.</p>"]},"rate":56,"rateN":5483},{"id":"62274","number":23,"category":"데이터분석","type":"choice","subject":"증거가 확실할 때 가설 검정으로 증명하고자 하는 것은?","choices":[{"n":1,"html":"귀무 가설"},{"n":2,"html":"영가설"},{"n":3,"html":"대립 가설"},{"n":4,"html":"기각 가설"}],"answer":[3],"explain":{"ai":["<p>데이터분석을 위한 가설 검정에서는 귀무 가설과 대립 가설이 있다. 증거가 확실할 때 가설 검정으로 증명하고자 하는 것은 대립 가설이다. 대립 가설은 원래 가정하고 있는귀무 가설과 반대되는 가설이며, 이를 증명하기 위해 데이터를 분석하고 통계적으로 검증한다. 데이터 분석의 결과가 대립 가설을 지지한다면, 귀무 가설을 기각하고 대립 가설을 채택하게 된다. 즉, 증거가 확실할 때는 대립 가설이 진실일 가능성이 높은 경우를 증명하고자 하므로, 정답은 대립 가설이다.</p>"]},"rate":61,"rateN":5330},{"id":"62275","number":24,"category":"데이터분석","type":"choice","subject":"다음 중 성격이 다른 한가지는?","choices":[{"n":1,"html":"K-Means"},{"n":2,"html":"Single Linkage Method"},{"n":3,"html":"DBSCAN"},{"n":4,"html":"주성분분석"}],"answer":[4],"explain":{"ai":["<p>클러스터링 알고리즘에는 여러 가지 방법이 있다. K-Means와 Single Linkage Method, DBSCAN은 모두 클러스터링 알고리즘에 속한다. 클러스터링은 데이터를 작은 그룹으로 나누는 것인데, K-Means는 중심점을 기준으로 거리 기반으로 클러스터링을 하고, Single Linkage Method는 가장 가까운 거리를 기준으로 클러스터링을하며, DBSCAN은 밀도 기반으로 클러스터링하는 알고리즘이다. </p>\n<p>주성분분석은 데이터의 차원을 줄이는 차원축소 알고리즘이다. 데이터를 분석하여 중요한 정보를 찾는 것이 목적이다. 데이터가 가진 특성을 유지하면서 데이터의 크기를 작게 만들어 비슷한 데이터를 찾는 것인데, 클러스터링 보다는 데이터의 속성이나 특성을 찾는 데 더 많이 사용된다.</p>"]},"rate":52,"rateN":6039},{"id":"62276","number":25,"category":"데이터분석","type":"choice","subject":"다음 중 스피어만 상관계수 관련 설명으로 틀린 것은?","choices":[{"n":1,"html":"스피어만 상관 계수는 비선형적인 관계를 나타낼 수 없다."},{"n":2,"html":"대상 자료는 서열 척도를 사용한다."},{"n":3,"html":"원시 데이터가 아니라 각 변수에 대해 순위를 매긴 값을 기반으로 한다."},{"n":4,"html":"연속형 외에 이산형 데이터도 사용 가능하다."}],"answer":[1],"explain":{"ai":["<p>스피어만 상관계수는 두 변수 간의 순위에 따라 상관관계를 측정하는 통계적 방법이다. 대상 자료는 서열 척도를 사용하며 원시 데이터가 아니라 각 변수에 대해 순위를 매긴 값을 기반으로 한다. 또한 연속형 외에 이산형 데이터도 사용 가능하다. 스피어만 상관계수는 비선형적인 관계를 나타낼 수 있다. 즉 순위 간의 관계가 선형적이지 않아도 상관관계를 측정할 수 있다. 따라서 스피어만 상관계수 관련 설명으로 틀린 것은 비선형적인 관계를 나타낼 수 없다는 설명이다.</p>"]},"rate":62,"rateN":5336},{"id":"62277","number":26,"category":"데이터분석","type":"choice","subject":"비지도 신경망으로 고차원의 데이터를 이해하기 쉬운 저차원의 뉴런으로 정렬하여 지도의 형태로 형상화하는 알고리즘을 무엇이라고 하는가?","choices":[{"n":1,"html":"SOM"},{"n":2,"html":"DBSCAN"},{"n":3,"html":"PCA"},{"n":4,"html":"EM 알고리즘"}],"answer":[1],"explain":{"ai":["<p>비지도 신경망을 이용해 고차원의 데이터를 저차원의 뉴런으로 정렬하여 지도의 형태로 형상화하는 알고리즘은 SOM이라고 한다._self-organizing map_의 약자로 자기 구성 지도를 의미한다. SOM은 입력 데이터의 패턴이나 구조를 자동으로 식별하고_visualize_하는 데 사용된다. 이는 mennes에게 고차원의 데이터를 이해하고 해석하기 쉽게 도와준다. 다른 선택지와 비교했을 때 SOM은 고차원 데이터를 저차원으로 감소시키고 시각화하는 데 특히 유용하다.</p>"]},"rate":70,"rateN":4984},{"id":"62278","number":27,"category":"데이터분석","type":"choice","subject":"다음의 설명에 해당하는 것은?","extra":"<pre class=\"contents\">공분산행렬 또는 상관계수 행렬을 사용해 모든 변수들을 가장 잘 설명하는 변수를 찾는 방법으로, 상관관계가 있는 변수들을 선형 결합에 의해 상관관계가 없는 새로운 변수를 만들고 분산을 극대화하는 변수로 축약하는 방법으로 새로운 변수들은 변수들의 선형결합으로 이루어져 있다.</pre>","choices":[{"n":1,"html":"요인 분석"},{"n":2,"html":"회귀 분석"},{"n":3,"html":"주성분 분석"},{"n":4,"html":"다차원 척도법"}],"answer":[3],"explain":{"ai":["<p>주어진 지문은 주성분 분석을 설명하고 있다. 주성분 분석은 여러 변수들의 상관관계를 이용해 새로운 변수를 생성하는 방법이다. 이 새로운 변수는 원래 변수들의 선형 결합으로 만들어지며, 이들을 이용해 데이터의 분산을 극대화하는 축 방향을 찾아내는 것이다.</p>\n<p>주성분 분석의 목적은 많은 변수들 중에서 대표 변수를 찾아내어 데이터의 차원을 축소하는 것이다. 이를 통해 변수 간의 복잡한 관계를 더 간단하게 이해할 수 있다. </p>\n<p>이 방법은 데이터 분석에서 매우 중요한 역할을 하며, 특히 많은 변수를 다루는 경우에 유용하다. 선형 결합을 통해 새로운 변수를 생성함으로써, 데이터의 본질을 더 잘 이해할 수 있도록 돕는다. </p>\n<p>따라서 주성분 분석은 여러 변수 간의 상관관계를 이용해 데이터의 분산을 극대화하는 새로운 변수를 만들어내는 방법으로, 정답은 3번 주성분 분석이 맞다.</p>"]},"rate":63,"rateN":5309},{"id":"62279","number":28,"category":"데이터분석","type":"choice","subject":"다음 중 확률 및 확률 분포에 관한 설명으로 부적절한 것은?","choices":[{"n":1,"html":"(사건A가 일어나는 경우의 수)/(일어날 수 있는 모든 경우의 수)를 P(A)라고 할 때 이를 A의 수학적 확률이라 한다."},{"n":2,"html":"한 사건 A가 일어날 확률을 P(A)라 할 때 반복시행에서 사건 A가 일어난 횟수를 R이라 하면, 상대도수 R/N은 N이 커짐에 따라 확률 P(A)에 가까워짐을 알 수 있다. P(A)를 사건 A의 통계적 확률이라 한다."},{"n":3,"html":"두 사건 A,B가 독립일 때 사건 B의 확률은 A가 일어났다는 가정하에서의 B의 조건부 확률과는 다르다."},{"n":4,"html":"표본공간에서 임의의 사건 A가 일어날 확률 P(A)는 항상 0과 1사이에 있다."}],"answer":[3],"explain":{"ai":["<p>확률 및 확률 분포와 관련된 설명 중 부적절한 것은 3번이다. </p>\n<p>여기서 설명하는 두 사건 A와 B가 독립일 때, 사건 B의 확률과 A가 일어났다는 가정하에서의 B의 조건부 확률은 사실 동일하다. 독립이라는 것은 사건 A의 발생 여부와 상관없이 사건 B의 발생 확률이 변하지 않는다는 것을 의미한다. 따라서 3번 설명이 부적절한 것이다. </p>\n<p>그 외의 선택지 1, 2, 4번은 모두 확률에 대한 올바른 설명이다. 1번은 수학적 확률을 정의하며, 2번은 통계적 확률과 상대도수와의 관계를 설명한다. 4번은 임의의 사건의 확률이 0과 1 사이에 있다는 사실을 언급한다.</p>"]},"rate":74,"rateN":4559},{"id":"62280","number":29,"category":"데이터분석","type":"choice","subject":"다음은 TV광고수에 따른 Sales에 대한 산점도이다. 이에 대한 설명으로 맞지 않은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"TV 광고가 증가할 수록 Sales도 증가하는 경향이 있다."},{"n":2,"html":"TV광고와 Sales는 양의 상관관계를 가진다."},{"n":3,"html":"tv광고가 증가할수록 Sales의 분산은 동일하다"},{"n":4,"html":"Sales를 설명하기 위해 TV광고를 독립변수로 하는 단순선형회귀모델은 적절하다"}],"answer":[3],"rate":89,"rateN":4149},{"id":"62281","number":30,"category":"데이터분석","type":"choice","subject":"Hitters dataset의 일부이다. 다음 설명 중 적절하지 않은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"Salary 변수 분포는 왼쪽 꼬리가 긴 분포를 가진다."},{"n":2,"html":"NewLeague 변수는 범주형 자료이다."},{"n":3,"html":"Hits 변수에는 결측값이 없음을 알 수 있다."},{"n":4,"html":"HmRun 변수의 최대값은 40이다"}],"answer":[1],"rate":68,"rateN":4783},{"id":"62282","number":31,"category":"데이터분석","type":"choice","subject":"모집단의 크기가 비교적 작을 때 주로 사용되며 한번 추출된 표본이 재 추출될 수 있는 표본 추출 방법은 무엇인가?","choices":[{"n":1,"html":"복원 추출법"},{"n":2,"html":"층화 추출법"},{"n":3,"html":"군집 추출법"},{"n":4,"html":"계층 추출법"}],"answer":[1],"explain":{"ai":["<p>모집단의 크기가 비교적 작을 때 주로 사용되는 표본 추출 방법은 복원 추출법이다. 이 방법은 한번 추출된 표본이 재 추출될 수 있어 표본의 크기가 커질 수록 모집단의 대표성을 더 잘 유지할 수 있다. 다른 방법들은 이러한 특성을 갖지 않는다. 층화 추출법은 모집단을 여러 층으로 나누어 추출한다. 군집 추출법은 모집단을 여러 군집으로 나누어 추출한다. 계층 추출법은 모집단을 여러 계층으로 나누어 추출한다. 하지만 이 방법들은 한번 추출된 표본이 재 추출될 수 있는 특성을 갖지 않는다. 따라서 모집단의 크기가 비교적 작을 때 주로 사용되는 표본 추출 방법은 복원 추출법이다.</p>"]},"rate":85,"rateN":4428},{"id":"62283","number":32,"category":"데이터분석","type":"choice","subject":"다음 닭 사료의 종류(feed)와 닭의 성장에 대한 boxplot 결과이다. 옳지 않은 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"이상치가 존재하지 않는 것을 알 수 있다."},{"n":2,"html":"casein의 경우horsebean보다 중위수가 크다"},{"n":3,"html":"soybean의 경우 meatmeal보다 최소값, 최대값이 모두 작다."},{"n":4,"html":"horsebean사료를 먹은 닭의 무게가 가장 작은 쪽에 분포해 있다."}],"answer":[1],"explain":{"user":["sunflower 이상치 존재"]},"rate":77,"rateN":4434},{"id":"62284","number":33,"category":"데이터분석","type":"choice","subject":"자료의 척도에 대한 설명으로 부적절한 것은?","choices":[{"n":1,"html":"명목 척도: 질적척도(Qualitative Scale)중 하나로 범주 또는 카테고리로 분류하는데 사용한다."},{"n":2,"html":"서열 척도: 대소 또는 높고 낮음 등의 순위만 제공할 뿐 양적인 비교는 할 수 없다."},{"n":3,"html":"등간 척도: 사칙연산이 가능하다."},{"n":4,"html":"비율 척도: 절대 0점이 존재하여 측정값 사이의 비율 계산이 가능한 척도이다."}],"answer":[3],"explain":{"ai":["<p>등간 척도는 일정한 간격으로 측정하지만 0점의 의미가 없을 수 있으며, 사칙연산이 모두 가능하다고 말할 수 없다. 등간 척도는 평균값은 계산할 수 있지만, 비율의 비교는 정확하지 않다. 따라서 명목 척도, 서열 척도, 비율 척도는 각각의 설명이 적절하지만 등간 척도의 설명이 부적절하다.</p>"]},"rate":66,"rateN":5175},{"id":"62285","number":34,"category":"데이터분석","type":"choice","subject":"다음 연관 분석에 대한 설명 중 잘못된 것은?","choices":[{"n":1,"html":"비목적성 분석 기법으로 계산이 간편하다."},{"n":2,"html":"대표적인 알고리즘으로 Aprior가 있다."},{"n":3,"html":"조건 반응으로 표현되는 연관 분석의 결과를 이해하기 쉽다."},{"n":4,"html":"품목 수가 증가해도 분석에 필요한 계산이 늘어나지 않는다."}],"answer":[4],"explain":{"ai":["<p>연관 분석은 데이터 간의关聯성을 분석하는 기법입니다. 연관 분석은 비목적성 분석 기법이기 때문에 어떤 특정한 목적이나 가설 없이 데이터의关聯성을 찾는 데 중점을 둡니다. 대표적인 알고리즘으로는 아프리オリ알고리즘이 있습니다. </p>\n<p>조건 반응으로 표현되는 연관 분석의 결과는 이해하기 쉽습니다. 연관 분석의 결과는 만약 이런 조건이면 저런 결과가 일어날 가능성이 높다라는 식으로 표현되기 때문입니다. </p>\n<p>하지만 연관 분석은 품목 수가 증가하면 분석에 필요한 계산도 함께 증가합니다. 이는 연관 분석이 각 품목 간의关聯성을 분석해야 하기 때문에 품목 수가 많아질수록 계산량도 늘어나기 때문입니다. 따라서 올바른 연관 분석에 대한 설명 중 잘못된 것은 품목 수가 증가해도 분석에 필요한 계산이 늘어나지 않는다는 것입니다.</p>"]},"rate":85,"rateN":4141},{"id":"62286","number":35,"category":"데이터분석","type":"choice","subject":"데이터 분할에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"데이터 마이닝 적용 후 결과의 신빙성 검증을 위해 데이터를 학습, 검증, 테스트 데이터로 나누어 사용한다."},{"n":2,"html":"검증용 데이터는 모델 성능 평가에 사용한다."},{"n":3,"html":"테스트용 데이터와 학습 데이터는 섞여서는 안된다."},{"n":4,"html":"학습 데이터를 사용해 학습을 진행한다."}],"answer":[2],"explain":{"ai":["<p>데이터 분할은 데이터 마이닝에서 중요하다. 데이터를 학습, 검증, 테스트 데이터로 나누는 이유는 모델의 성능을 평가하고 과적합을 방지하기 위해서다. </p>\n<p>학습 데이터는 모델을 학습시키는 데 사용된다. \n검증 데이터는 모델의 하이퍼파라미터를 튜닝하는 데 사용되며, 이는 모델의 성능을 최적화하는 것을 의미한다. \n테스트 데이터는 모델의 성능을 최종적으로 평가하는 데 사용된다.</p>\n<p>따라서 2번 항목인 검증용 데이터는 모델 성능 평가에 사용한다는 설명은 정확하지 않다. \n검증 데이터는 모델의 하이퍼파라미터를 튜닝하는 데 사용된다. \n따라서 정답은 2번이다.</p>"]},"rate":58,"rateN":5486},{"id":"62287","number":36,"category":"데이터분석","type":"choice","subject":"다음 표준 오차에 대한 설명 중 틀린것은?","choices":[{"n":1,"html":"표본 평균이 모 평균과 얼마나 떨어져 있는가를 나타낸다."},{"n":2,"html":"표준 오차는 δ / √N 로 구한다."},{"n":3,"html":"표준오차 95%는 신뢰구간에 모수의 참값이 포함되어 있음을 나타낸다."},{"n":4,"html":"더 작은 표준 오차는 추정치가 모집단 파라미터를 더 정확하게 반영한다는 것을 나타낸다."}],"answer":[3],"explain":{"ai":["<p>표준 오차는 데이터의 신뢰도를 나타내는 지표 중 하나로, 표본 평균의 표준 편차를 의미한다. 일반적으로 표준 오차는 δ / √N 로 계산되며, 이는 표본 크기가 증가할수록 표준 오차가 감소함을 의미한다. </p>\n<p>정답인 3번은 표준 오차 95%가 신뢰구간에 모수의 참값이 포함되어 있음을 나타낸다는 설명이 틀렸다는 것을 의미한다. 신뢰구간은 실제로 모수에 대한 추정을 하기 위해 사용되며, 95% 신뢰구간이란 약 95%의 확신을 갖고 해당 구간 안에 모수의 참값이 있을 것으로 예상할 수 있다는 것이지, 표준 오차 95%가 그 역할을 하는 것은 아니다. </p>\n<p>따라서, 3번은 표준 오차에 대한 설명 중 틀린 것이다.</p>"]},"rate":54,"rateN":5665},{"id":"62288","number":37,"category":"데이터분석","type":"choice","subject":"아래의 불순도 측정 결과를 사용해서 구한 지니 지수는 얼마인가?","extra":"<pre class=\"contents\">●●◆●●</pre>","choices":[{"n":1,"html":"0.5"},{"n":2,"html":"0.32"},{"n":3,"html":"0.48"},{"n":4,"html":"0.38"}],"answer":[2],"explain":{"ai":["<p>지니 지수는 불균형 정도나 불평등 정도를 측정하는 방법 중 하나로, 주어진 불순도 측정 결과를 사용해서 구한 지니 지수를 계산해야 한다. </p>\n<p>지니 지수는 특정 집단 내의 분포도หร�인 분포의 척도로 가장 经常적으로 사용되는 통계량 중 하나이다. 지니 계수는 0과 1 사이의 값을 가지며 0에 가까울수록 완전한均等 상태, 1에 가까울수록 비율의 편중이 심함을 의미한다.</p>\n<p>지니 지수를 계산하는 방법은 여러 가지이지만 일반적으로는 로렌즈 곡선을 사용하여 계산한다. 로렌즈 곡선은 실제 분포도와 완전한均等 상태의 분포도를 비교하여 지니 지수를 계산하는 그래프이다.</p>\n<p>지니 지수를 계산하는 공식을 사용하여 주어진 불순도 측정 결과를 넣으면 지니 지수는 0.32로 계산된다. </p>\n<p>따라서 정답은 2번이다. 지니 지수는 분포의 불균형 정도를 측정하는 지표 중 하나로 주어진 데이터에서 계산한 결과 0.32가 가장 적절한 지니 지수이다.</p>"]},"rate":69,"rateN":3949},{"id":"62289","number":38,"category":"데이터분석","type":"choice","subject":"어떤 슈퍼마켓 고객 6명의 장바구니 별 구입 품목이 다음과 같다고 한다면, \r\n연관 규칙(콜라→맥주)의 지지도는?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"0.6"},{"n":2,"html":"0.4"},{"n":3,"html":"0.5"},{"n":4,"html":"0.3"}],"answer":[3],"rate":76,"rateN":4478},{"id":"62290","number":39,"category":"데이터분석","type":"choice","subject":"다음의 품목/거래량 표를 사용하여 연관 규칙(딸기→사과)의 향상도는 무엇인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"0.3"},{"n":2,"html":"0.3 / (0.7*0.45)"},{"n":3,"html":"0.3 / 0.7"},{"n":4,"html":"0.3 / (0.7 + 0.45)"}],"answer":[2],"rate":74,"rateN":4034},{"id":"62291","number":40,"category":"데이터분석","type":"choice","subject":"다음 설명에 해당되는 앙상블 기법은?","extra":"<pre class=\"contents\">여러 개의 붓스트랩 자료를 생성하고 각 붓스트랩 자료에 예측 모형을 만든 후 결합하여 최종 예측 모형을 만드는 방법.</pre>","choices":[{"n":1,"html":"배깅(Bagging)"},{"n":2,"html":"Voting"},{"n":3,"html":"부스팅(Boosting)"},{"n":4,"html":"Stacking"}],"answer":[1],"explain":{"ai":["<p>앙상블 기법은 여러개의 모델을 결합하여 더 나은 성능의 모델을 만들기위한 방법입니다. 주어진 설명은 여러개의 붓스트랩 자료를 생성하고 각 자료에 예측모형을 만들고 최종적으로 예측모형을 결합한다는 내용입니다. </p>\n<p>이러한 설명에 해당하는 앙상블 기법은 배깅입니다. 배깅은 여러개의 붓스트랩 자료를 생성하고 각 자료에 동일한 모델을 적용한 후 예측 결과를 결합하여 최종 예측 결과를 만듭니다. </p>\n<p>배깅은 과적합방지를위해 많이 사용됩니다. 부스팅은 모델을 순차적으로 학습하고 예측 결과를 결합하여 사용하고 스택킹은 각 모델의 예측 결과를 메타 모델에 입력하여 사용하고 보팅은 각 모델의 예측결과를 투표에 의하여 결합하여 사용합니다. </p>\n<p>배깅은 각 모델이 독립적으로 학습되고 예측 결과가 평균화되어 과적합을 방지합니다.</p>"]},"rate":74,"rateN":4675},{"id":"62292","number":41,"category":"데이터분석","type":"choice","subject":"군집분석 관련 설명으로 틀린 것은?","choices":[{"n":1,"html":"계층적 군집 분석은 사전에 군집 수 k를 설정할 필요가 없는 탐색적 모형이다."},{"n":2,"html":"집단 간 이질화, 집단 내 동질화 모두 낮은 것을 군집으로 선택한다."},{"n":3,"html":"K-means 군집은 잡음이나 이상값에 영향을 받기 쉽다."},{"n":4,"html":"군집분석은 비지도학습이다."}],"answer":[2],"explain":{"ai":["<p>군집분석은 데이터를 여러개의 군집으로 나누는 분석기법입니다. 계층적 군집 분석은 사전에 군집 수를 설정할 필요가 없으며, 데이터의 특성을 가지고 군집을 형성합니다. K-means 군집분석은 군집 수를 설정하고, 설정한 군집의 중심점을 기준으로 데이터를 할당하며, 이때 잡음이나 이상값에 의해 군집의 중심점이 왜곡될 수 있습니다. </p>\n<p>군집분석에서 집단 간 이질화는 높이고, 집단 내 동질화는 낮추는 것이 목표입니다. 집단 간 이질화란 군집 간의 차이를 말하며, 이는 높을수록 좋습니다. 집단 내 동질화란 군집 내의 데이터 간의 유사성을 말하며, 이는 낮을수록 좋습니다. 따라서 집단 간 이질화는 높이고, 집단 내 동질화를 낮출 수 있는 군집구조를 선택하는 것이 올바릅니다. </p>\n<p>因此, 정답은 2번입니다.</p>"]},"rate":63,"rateN":5180},{"id":"62293","number":42,"category":"데이터분석","type":"choice","subject":"신경망 노드 중 무작위로 노드를 선정하여 다수의 모형을 구성하고 학습한 뒤 각 모형의 결과를 결합해 분류 및 예측하는 기법을 무엇이라고 하는가?","choices":[{"n":1,"html":"Mini-Batch"},{"n":2,"html":"bagging"},{"n":3,"html":"Drop-out"},{"n":4,"html":"AdaBoost"}],"answer":[4],"wiki":[{"title":"드롭아웃","url":"https://itwiki.kr/w/드롭아웃"}],"explain":{"ai":["<p>주어진 문제에서 질문하는 기법은 여러 개의 신경망 모델을 독립적으로 학습시킨 후 그 결과를 결합하여 예측 성능을 향상시키는 방법에 대한 것이다. </p>\n<ol>\n<li><strong>Mini-Batch</strong>는 학습 과정에서 데이터를 작은 배치로 나누어 처리하는 방법으로, 모델의 다양성을 직접적으로 증가시키는 기법이 아니다.</li>\n<li><strong>Bagging</strong>은 주로 결정 트리 모델에서 사용되는 기법으로, 여러 개의 모델을 무작위 샘플링된 데이터로 학습시켜 예측을 결합한다. 신경망에 특화된 용어는 아니다.</li>\n<li><strong>Drop-out</strong>은 개별 신경망 모델 내에서 학습 중 일부 노드를 임의로 비활성화하여 과적합을 방지하는 기법이다. 여러 모델을 생성하고 결합하는 방식이 아니다.</li>\n<li><strong>AdaBoost</strong>는 약한 학습기들을 순차적으로 학습시키며, 이전 모델의 오류에 더 큰 가중치를 부여해 새로운 모델을 향상시키는 앙상블 기법이다. 이 문제의 맥락에서, 정답은 사실상 <strong>Bagging의 신경망 적용 형태에 더 가깝지만</strong> 주어진 옵션 중에서는 <strong>AdaBoost가 가장 가까운 개념을 대표</strong>하는 것으로 오해의 소지가 있긴 하다. 그러나 주어진 보기 중에서 여러 독립적 모델의 결과를 결합하는 개념에 가장 근접한 것으로 해석될 수 있는 선택지가 없으므로, 문제의 의도를 정확히 반영하지 않는다면, 가장 적합한 답변을 고르라는 맥락에서는 주어진 정보 내에서는 정확한 정답이 명시적으로 주어진 옵션에 없는 상황이다. </li>\n</ol>\n<p>하지만 문제의 정답이 명시적으로 4번(AdaBoost)으로 지정되었으므로, 이는 문제 설계상의 특정 의도나 제한된 선택지 내에서의 최선의 선택으로 이해되어야 할 것이다. 정확한 맥락에서는 Bagging의 신경망 적용 형태를 묻는 것이 더 적절했을 것이다.</p>"]},"rate":44,"rateN":6385},{"id":"62294","number":43,"category":"데이터분석","type":"choice","subject":"다음 회귀분석의 결과 해석으로 틀린 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"결정계수는 0.9588이다."},{"n":2,"html":"5% 유의수준에서 모형은 통계적으로 유의미 하다."},{"n":3,"html":"Time이 1단 증가하면 Weight가 평균적으로 8.8 증가한다."},{"n":4,"html":"추정된 회귀식은 weight = 24.4654 + 7.9879 * Time이다."}],"answer":[3],"rate":77,"rateN":4274},{"id":"62295","number":44,"category":"데이터분석","type":"choice","subject":"독립 변수간 상관관계가 높아 많은 문제점을 발생하는 현상으로 회귀계수의 분산을 증가시켜 불안정하고 해석하기 어렵게 만들게 되는 것을 다중 공선성이라고 한다. 이것의 해결 방법으로 사용할 수 있는 것은?","choices":[{"n":1,"html":"주성분 분석"},{"n":2,"html":"교차 분석"},{"n":3,"html":"오차 분석"},{"n":4,"html":"연관 분석"}],"answer":[1],"explain":{"ai":["<p>다중 공선성은 독립 변수 간 상관관계가 높아 회귀 계수의 분산을 증가시켜 불안정하고 해석하기 어렵게 만드는 현상입니다. 이런 문제를 해결하는 방법 중 하나는 주성분 분석입니다. 주성분 분석은 상관관계가 높은 변수들을 몇 개의 주성분으로 축소시켜 변수 간 상관관계를 줄이는 방법입니다. 이렇게 하면 다중 공선성의 문제를 완화하여 회귀 분석의 안정성과 해석성을 향상시킬 수 있습니다. </p>\n<p>주성분 분석 외에도 다른 방법들이 있을 수 있지만 주성분 분석은 다중 공선성을 해결하는 데 많이 사용되는 방법입니다. 다른 보기 중 교차 분석, 오차 분석, 연관 분석은 다중 공선성을 해결하는 데 사용되는 방법은 아닙니다. 그러므로 다중 공선성을 해결하는 데 주성분 분석을 사용할 수 있습니다.</p>"]},"rate":70,"rateN":4839},{"id":"62296","number":45,"category":"데이터분석","type":"short","subject":"시계열 분석에서 시계열 수준과 분산에 체계적인 변화가 없고, 주기적 변동이 없다는 것으로 미래는 확률적으로 과거와 동일하다는 것을 의미하는 용어는?","shortAnswer":"정상성","explain":{"ai":["<p>정상성(Stationarity)은 시계열 분석에서 중요한 개념으로, 시간이 지나도 시계열의 평균 수준과 분산이 일정하게 유지되고, 체계적인 경향성이나 영역별 변동(주기적 요소 포함)이 없다는 특징을 지닙니다. 이 상태에서는 과거의 패턴이 미래 예측에 직접적으로 적용될 수 있으며, 통계적 특성이 시간에 따라 변하지 않으므로 과거 데이터를 바탕으로 미래의 값을 확률적으로 예측할 때 일관성 있는 모델을 구축할 수 있습니다. 따라서 주어진 조건에 따라 미래가 과거와 동일한 확률적 특성을 유지한다는 의미에서 정답은 정상성입니다.</p>"]}},{"id":"62297","number":46,"category":"데이터분석","type":"short","subject":"다음 오분류표를 사용하여 F1 Score를 구하시오.","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","shortAnswer":"1/5"},{"id":"62298","number":47,"category":"데이터분석","type":"short","subject":"다음 빈칸에 알맞은 단어는?","extra":"<pre class=\"contents\">완전 연결법이라고도 하며, 두 군집 사이의 거리를 군집에서 하나씩 관측 값을 뽑았을 때 나타날 수 있는 거리의 (           )을 측정한다.</pre>","shortAnswer":"최댓값","explain":{"ai":["<p>해당 문맥에서 완전 연결법이란, 두 군집 사이의 거리를 계산할 때 각 군집에서 하나씩 관측 값을 뽑았을 때 나타날 수 있는 거리 중에서 최댓값을 사용하여 두 군집의 거리를 결정하는 방식을 말합니다. 이는 두 군집 사이에 있는 가장 먼 거리를 기준으로 군집을 분리하거나 合병하는 과정을 의미합니다. 이러한 방법은 군집 분석에서 군집 간의 거리를 결정하고 군집의 분리 또는 합병 여부를 결정하는 데 사용됩니다.</p>"]}},{"id":"62299","number":48,"category":"데이터분석","type":"short","subject":"다음 주성분 분석 결과에서 주성분 1개를 사용했을 때 분산을 구하시오.","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","shortAnswer":"57.5%"},{"id":"62300","number":49,"category":"데이터분석","type":"short","subject":"생물학적 진화과정을 모방하여 최적화 및 검색 문제를 해결하는데 사용되는 계산 알고리즘으로 다양한 해를 탐색하고 선택,교차,변이와 같은 유전 연산을 통해 최적의 해를 찾아내는데 효과적인 알고리즘은?","shortAnswer":"유전 알고리즘","explain":{"ai":["<p>داده를 처리하고 최적의 해결책을 찾는 데 사용되는 계산 알고리즘 중에서 효과적인 알고리즘은 유전 알고리즘입니다. 이 알고리즘은 생물학적 진화과정을 모방하여 다양한 해를 탐색하고, 선택, 교차, 변이와 같은 유전 연산을 통해 최적의 해를 찾아냅니다. 유전 알고리즘은 복잡한 문제를 해결하는 데에 효과적이며, 많은 분야에서 적용되고 있습니다. 이는 자연선택, 유전, 돌연변異와 같은 생물학적 원리를 바탕으로 최적화 문제를 풀기 위해 만들어졌습니다. 유전 알고리즘을 사용하면 최적의 해를 찾아내는 데에 유용하며, 다양한 문제에 적용할 수 있습니다.</p>"]}},{"id":"62301","number":50,"category":"데이터분석","type":"short","subject":"모집단을 먼저 서로 겹치지 않는 여러개의 층으로 분할한 후, 각 층에서 단순 임의 추출법에 따라 배정된 표본을 추출하는 방법","shortAnswer":"층화 추출법","explain":{"ai":["<p>조사나 실험의 대상이 되는 큰 그룹을 먼저 서로 겹치지 않는 여러개의 소그룹으로 나눈 후, 각 소그룹에서 표본을 추출하는 방법을 말한다. 이렇게 하면 대상 전체를 대표할 수 있는 표본을 추출할 수 있어 더 정확한 결과를 얻을 수 있다. 층을 나누는 기준은 조사나 실험의 목적에 따라 다를 수 있다. 예를 들어 성별, 연령, 직업 등 여러 기준으로 나눌 수 있다. 각 층에서 단순 임의 추출법에 따라 표본을 추출하면 앞에서 나눈 층에 해당하는 표본이 추출된다.</p>"]}}]};